 */
class CongesRepository extends \Doctrine\ORM\EntityRepository
{

        public function findEnConge($user, $natreq = 0, $mois = 0)
        {
                /*         * ********************************* */
                $infoService = ($user->getAgent()->retour_service());
                //Tableau de l'arborscence des service de l'agent
                $TabServ = explode(',', $infoService['tab_imput']);
                //Code Service de l'agent
                $serviceId = $infoService['service'];
                //Libellé du Service
                $niveau = count($TabServ) - 1;
                $now = new \Datetime();

                /*         * ********************************* */
                $qb = $this->createQueryBuilder('c')
                        ->join('c.agent', 'a');

                switch ($natreq) {
                        case 0: //FindEnConge
                                //pour Congé
                                $qb->andWhere($user->getAgent()->getServiceActuelWhere('a', 'Direction'))
                                        ->andWhere(":niveau = :niveau")
                                        ->andWhere("c.datedebut <= :now")
                                        ->andWhere("c.datefin >= :now")
                                        ->andWhere("c.etat in (1,3)")
                                        ->orderBy('c.datefin', 'ASC')
                                        ->setParameter("niveau", 0)
                                        ->setParameter("now", $now);
                                $qb->setParameter("Direction", $user->getAgent()->getServiceActuel());




                                break;
                        case 1: //Find StatCongé
                                //pour Congé
                                $qb->andWhere($user->getAgent()->getServiceActuelWhere('a', 'Direction'))
                                        ->select('distinct Month(c.datedebut) as mois, count(c.id) as total')
                                        // ->andWhere("c.niveau = 0 ")
                                        ->andWhere("Year(c.datedebut)=:now")
                                        ->andWhere("c.etat in (3,4)")
                                        ->groupBy("mois")
                                        ->setParameter("now", date('Y')) //Année en cours
                                        ->setParameter("Direction", $user->getAgent()->getServiceActuel());;
                                break;
                        case 2: //Find Details
                                //pour Congé
                                $qb->andWhere($user->getAgent()->getServiceActuelWhere('a', 'Direction'))
                                        // ->select('distinct Month(c.datedebut) as mois, count(distinct c.id) as total')
                                        //->andWhere("c.niveau = 0 ")
                                        ->andWhere("Year(c.datedebut)=:now")
                                        ->andWhere("Month(c.datedebut)=:mois")
                                        ->andWhere("c.etat in (3,4)")
                                        ->setParameter("now", date('Y'))
                                        ->setParameter("mois", $mois)
                                        ->setParameter("Direction", $user->getAgent()->getServiceActuel());
                                break;
                        case 3: //FindAvenir
                                //pour congé
                                $qb->andWhere($user->getAgent()->getServiceActuelWhere('a', 'Direction'))
                                        ->andWhere("c.datedebut > :now")
                                        ->andWhere("c.datefin >= :now")
                                        ->andWhere("c.etat in (0,1)")
                                        ->orderBy('c.datedebut', 'ASC')
                                        ->setParameter("now", $now);
                                $qb->setParameter("Direction", $user->getAgent()->getServiceActuel());

                                break;

                        default:
                                break;
                }


                return $qb->getQuery()->getResult();
        }

        public function findCongeAll($typeConges = 0, $niveau = 0)
        {
                $qb = $this->createQueryBuilder('c')
                        ->join('c.agent', 'a');
                //->addSelect('a')
                /*
          if($niveau==0){//Niveau 1: Service_ Direction
          $qb->Where("a.code_dg = :Direction");
          }
          if($niveau==1){//Niveau 2; Sous Direction Section
          $qb->Where("a.code_dc = :Direction");
          }
          if($niveau==2){//Niveau 3: Direction Service Rattaché
          $qb->Where("a.code_sd = :Direction");
          } */
                $qb->andWhere("c.niveau = :niveau")
                        ->orderBy('c.datecreation', 'DESC');
                if ($typeConges) {
                        $qb->andWhere("c.typeConges = :typeConges")
                                ->setParameter("typeConges", $typeConges);
                }
                $qb->setParameter("niveau", $niveau);
                //->setParameter("Direction", $serviceId);

                return $qb->getQuery()->getResult();
        }

        public function findCongeParam($typeConges = 1, $serviceId, $niveau, $etat = null, $expire = 1, $agent = null)
        {

                $niveaux = array_values(range(5, $niveau - 1));

                if ($agent != null) {
                        $matricule = ($agent->getId());
                }

                $qb = $this->createQueryBuilder('c')
                        ->join('c.agent', 'a');




                //->addSelect('a')
                if ($typeConges == 0) {
                        /*


              if ($agent->getServiceActuel() instanceof SousDirection) {
              $qb->Where("a.code_sd = :Direction");
              } elseif ($agent->getServiceActuel() instanceof Direction) {
              $qb->Where("a.code_dc = :Direction");
              } elseif ($agent->getServiceActuel() instanceof DirectionGenerale) {
              $qb->Where("a.code_dg = :Direction");
              }
             */



                        if ($niveau == 0) {
                                //Niveau 1: Service_ Direction
                                $qb->Where("a.code_dg = :Direction");
                        }
                        if ($niveau == 1) {
                                //Niveau 2; Sous Direction Section
                                $qb->Where("a.code_dc = :Direction");
                        }
                        if ($niveau == 2) {
                                //Niveau 3: Direction Service Rattaché
                                $qb->Where("a.code_sd = :Direction");
                        }
                        if ($niveau == 3) {
                                //Niveau 3: Direction Service Rattaché
                                $qb->Where("a.code_sc = :Direction");
                        }


                        $qb->setParameter("Direction", $serviceId)
                                ->andWhere('c.agent <>:matricule')
                                ->setParameter("matricule", $matricule);
                        if ($agent->getFonction()->getId() == 10) {
                                $qb->andWhere("a.Fonction in (5,7)")
                                        ->andWhere("a.Fonction in (5,7)")
                                        ->orWhere("a.Direction in (12,13,14,15,16,17,18,19)");
                        }
                } elseif ($typeConges == 1) { //Autres Services
                        // $qb->Where("c.typeConges = :typeConges")
                        $qb->Where("a.code_dc <> :Direction")
                                ->andWhere("c.niveau =0")
                                ->andWhere('a.Fonction not in (5,7)') //Directeur Chef de Service Rattaché
                                ->setParameter("Direction", $serviceId);
                } elseif ($typeConges == 2) {
                        //Pour l'utilisateur connecté
                }
                //$qb->andWhere("c.niveau in (:niveau)");
                if ($etat != null and count($etat) >= 1) {
                        $qb->andWhere("c.etat in (:etat)")
                                ->setParameter("etat", $etat);
                }
                if ($expire == 1) { //Actif
                        $qb->andWhere("c.datereprise IS NULL ");
                } elseif ($expire == 0) { //expiré
                        $qb->andWhere("c.datereprise IS NOT NULL");
                }
                $qb->orderBy('c.datecreation', 'DESC');
                //      ->setParameter("niveau", $niveaux)
                //dump($qb->getQuery());die;
                return $qb->getQuery()->getResult();
        }

        public function findCongeParamId($id, $serviceId, $niveau)
        {
                $niveaux = array_values(range(5, $niveau - 1));
                $qb = $this->createQueryBuilder('c')
                        ->join('c.agent', 'a');
                //->addSelect('a')
                if ($niveau == 0) {
                        //Niveau 1: Service_ Direction
                        $qb->Where("a.code_dg = :Direction");
                }
                if ($niveau == 1) {
                        //Niveau 2; Sous Direction Section
                        $qb->Where("a.code_dc = :Direction");
                }
                if ($niveau == 2) {
                        //Niveau 3: Direction Service Rattaché
                        $qb->Where("a.code_sd = :Direction");
                }
                $qb->andWhere("c.id = :id")
                        // ->andWhere("c.niveau in (:niveau)")
                        ->orderBy('c.datecreation', 'DESC')
                        // ->setParameter("niveau", $niveaux)
                        ->setParameter("id", $id)
                        ->setParameter("Direction", $serviceId);

                return $qb->getQuery()->getOneOrNullResult();
        }

        public function findCongeReceive($Direction, $etat)
        {
                $qb = $this->createQueryBuilder('c')
                        ->join('c.agent', 'a')
                        ->addSelect('a')
                        ->Where("a.Direction = :Direction")
                        ->andWhere("c.etat >= :etat")
                        ->orderBy('c.datecreation,c.etat', 'DESC')
                        ->setParameter("etat", $etat)
                        ->setParameter("Direction", $Direction);

                return $qb->getQuery()->getResult();
        }

        public function findCongeAutre($Direction, $etat)
        {
                $qb = $this->createQueryBuilder('c')
                        ->join('c.agent', 'a')
                        ->addSelect('a')
                        ->Where("a.Direction != :Direction")
                        ->andWhere("c.etat >= :etat")
                        ->setParameter("Direction", $Direction)
                        ->orderBy('c.id', 'DESC')
                        ->setParameter("etat", $etat);
                return $qb->getQuery()->getResult();
        }

        public function sumConge($agentid, $typeConges, $etat = 0)
        {
                if ($typeConges == 1) {
                        $exercice = date('Y') - 1;
                } else {
                        $exercice = date('Y');
                }
                $qb = $this->createQueryBuilder('c');
                $qb->select('sum(c.nbrejours) as somme')
                        //  $qb->select('ex.annee')
                        ->join('c.exercice', 'ex')
                        ->where("c.agent =:agent")
                        ->andWhere("c.typeConges =:typeConges")
                        //->andWhere("c.niveau >=:niveau")
                        ->andWhere("c.etat >=:etat")
                        ->andWhere("ex.annee = :exercice")
                        ->setParameter("agent", $agentid)
                        //  ->setParameter("niveau", $niveau)
                        ->setParameter("etat", $etat)
                        ->setParameter("typeConges", $typeConges)
                        ->setParameter("exercice", $exercice);
                return $qb->getQuery()->getOneOrNullResult();
        }

        public function MaxDateReprise($agentid)
        {
                $qb = $this->createQueryBuilder('c');
                $qb->select('c, MAX(c.datefin)')
                        ->Where("c.agent =:agent")
                        ->setParameter("agent", $agentid);
                //->setMaxResults(1);
                return $qb->getQuery()->getOneOrNullResult();
        }

        /*
      si cessation et datedepart >=datejour et datereprise<datejour
      impossible de passer demande de congé et etat congé encour */

        public function EtatConge($agentid)
        {
                $qb = $this->createQueryBuilder('c');
                $qb->select('max(c.id) as maxid')
                        ->where("c.agent =:agent")
                        ->andWhere("c.datedebut <=:date")
                        ->andWhere("c.datefin >:date")
                        ->andWhere("c.etat =3") //Cessation généré
                        ->setParameter("agent", $agentid)
                        ->setParameter("date", date('Y-m-d'));
                return $qb->getQuery()->getOneOrNullResult();
        }

        //Congé en Attente Non Validé par le responsable
        public function monserviceWork($respo, $etat = 0, $service = null)
        {
                $qb = $this->createQueryBuilder('c')
                        ->leftjoin('c.validation', 'v')
                        ->leftjoin('c.agent', 'agt')
                        ->leftjoin('v.agent', 'av')
                        ->leftjoin('av.Fonction', 'f')
                        ->where('1=1');
                switch ($etat) {
                        case 0: //EN attente
                                $qb->andWhere($respo->getServiceActuelWhere('agt', 'Direction'))
                                        ->andWhere('av.id is null or f.priorite> :priorite')
                                        ->andWhere('c.etat=0')
                                        ->andWhere('c.agent <> ' . $respo->getId());
                                break;
                        case 1: //Validé
                                $qb->andWhere($respo->getServiceActuelWhere('agt', 'Direction'))
                                        ->andWhere('f.priorite <= :priorite or c.etat=2')
                                        // ->orWhere('c.etat=2')
                                        ->andWhere('c.agent <> ' . $respo->getId());;
                                break;
                        case 2: //Transmis au Ressources Humaines
                                //$qb->andWhere('f.priorite <= :priorite');
                                $qb->Where("agt.Direction <> :Direction")
                                        ->andWhere('f.priorite <= :priorite or c.typeConges <> 1')
                                        ->andWhere("c.niveau = 0")
                                        ->andWhere("c.etat = 0")
                                        ->andWhere('agt.Fonction not in (5,7)') //Directeur Chef de Service Rattaché
                                        //->orWhere("agt.Direction in (12,13,14,15,16,17,18,19) and c.etat = 0")

                                ;
                                break;
                        case 3: //Transmis au Ressources Humaines & Cessation Généré
                                $qb->Where("agt.Direction <> :Direction")
                                        ->andWhere('f.priorite <= :priorite or c.typeConges <> 1')
                                        ->andWhere("c.niveau = 0")
                                        ->andWhere("c.etat = 1")
                                        ->andWhere('agt.Fonction not in (5,7)');
                                break;
                        case 4: //Reprise
                                $qb->andWhere($respo->getServiceActuelWhere('agt', 'Direction'))
                                        ->andWhere('f.priorite <= :priorite')
                                        ->andWhere("c.niveau = 0")
                                        ->andWhere("c.etat = 1")
                                        ->andWhere('agt.Fonction not in (5,7)');
                                break;
                        case 5: //Reprise Généré
                                $qb->andWhere($respo->getServiceActuelWhere('agt', 'Direction'))
                                        ->andWhere('f.priorite <= :priorite')
                                        ->andWhere("c.niveau = 0")
                                        ->andWhere("c.etat = 3")
                                        ->andWhere('agt.Fonction not in (5,7)');
                                break;
                        case 6: //Reprise Généré autres services
                                $qb->andWhere('agt.Direction <> :Direction')
                                        ->andWhere('f.priorite <= :priorite')
                                        ->andWhere("c.niveau = 0")
                                        ->andWhere("c.etat = 3")
                                        ->andWhere('agt.Fonction not in (5,7)');
                                break;
                        case 7: //Reprise et Cessation à Imprimer
                                $qb->andWhere(':priorite=:priorite')
                                        //->andWhere("c.niveau = 0")
                                        ->andWhere(":Direction = :Direction")
                                        //->andWhere("c.etat = 3 or c.etat = 1")
                                        //->andWhere("c.etatImpression = 2 or c.etatImpression = 4")
                                        ->andWhere("(c.etat = 1 and c.etatImpression < 2 and c.numCessation is null)"
                                                . "or (c.etat = 3 and c.etatImpression < 4 and  c.numReprise is null)")
                                        //->orWhere("c.etat = 3 and c.etatImpression < 4 and  c.numReprise is null")
                                        //->andWhere('agt.Fonction not in (5,7)')
                                ;
                                break;
                        case 8: //BAc à Numérisation
                                $qb->andWhere(':priorite=:priorite')
                                        ->andWhere("c.niveau = 0")
                                        ->andWhere(":Direction = :Direction")
                                        ->andWhere("c.etat = 1 and c.etatImpression = 2 and c.numCessation is null")
                                        ->orWhere("c.etat = 3 and c.etatImpression = 4 and  c.numReprise is null")

                                        //->andWhere('agt.Fonction not in (5,7)')
                                ;
                                break;
                        case 9: //Acte à RéImprimer
                                $qb->andWhere(':priorite=:priorite')
                                        // ->andWhere("c.niveau = 0")
                                        //->orWhere(":Direction = :Direction")
                                        ->andWhere("(:Direction = :Direction) and "
                                                . "((c.etat = 1 and c.etatImpression <= 2 and c.numCessation is null)"
                                                . "or (c.etat = 3 and c.etatImpression <= 4 and  c.numReprise is null))")

                                        //->andWhere('agt.Fonction not in (5,7)')
                                ;
                                break;
                                //CAS DES DIRECTEURS & AGENTS CABINET
                        case 10: //Transmis au Ressources Humaines RESPO
                                //$qb->andWhere('f.priorite <= :priorite');
                                $qb->andWhere('f.priorite <= :priorite')
                                        ->andWhere("c.niveau = 0")
                                        ->andWhere(":Direction = :Direction")
                                        ->andWhere('agt.Fonction in (5,7) and c.etat = 0')
                                        ->orWhere("agt.Direction in (12,13,14,15,16,17,18,19) and c.etat = 0");
                                break;
                        case 11: //Transmis au Ressources Humaines & Cessation Généré RESPO
                                $qb->andWhere('f.priorite <= :priorite')
                                        ->andWhere("c.niveau = 0")
                                        ->andWhere(":Direction = :Direction")
                                        ->andWhere('agt.Fonction in (5,7) and c.etat = 1')
                                        ->orWhere("agt.Direction in (12,13,14,15,16,17,18,19) and c.etat = 1");
                                break;
                        case 12: //Reprise Généré autres services RESPO
                                $qb->andWhere('f.priorite <= :priorite')
                                        ->andWhere(":Direction = :Direction")
                                        ->andWhere('agt.Fonction in (5,7) and c.etat = 3')
                                        ->orWhere("agt.Direction in (12,13,14,15,16,17,18,19) and c.etat = 3");
                                break;
                        case 13: //Reprise et Cessation à Imprimer
                                $qb->andWhere(':priorite = :priorite')
                                        ->andWhere("c.niveau = 0")
                                        ->andWhere(":Direction = :Direction")
                                        ->andWhere(
                                                '((agt.Fonction in (5,7) or agt.Direction in (12,13,14,15,16,17,18,19)) or agt.Direction in (12,13,14,15,16,17,18,19)   and c.etat = 3 and '
                                                        . '((c.etat = 1 and c.etatImpression < 2 and c.numCessation is null)'
                                                        . ' or(c.etat = 3 and c.etatImpression < 4 and  c.numReprise is null)))'
                                        );
                                break;
                        default:
                                $qb->andWhere('f.priorite <= :priorite');
                                break;
                }



                $qb->orderBy('c.id', 'desc')
                        ->setParameter("Direction", $respo->getServiceActuel())
                        ->setParameter("priorite", $respo->getFonction()->getPriorite());;

                if ($service != null && $service) {
                        $qb->andWhere($qb->expr()->In('agt.Direction', ':service'))
                                //->andWhere('agt.Direction<> :dir')
                                //->setParameter("dir", $respo->getServiceActuel())
                                ->setParameter("service", explode(",", $service));
                }
                if ($respo->getFonction()->getId() == 10) {
                        $qb->andWhere('agt.Fonction in (5,7,9) or agt.Direction in (15,16,17,18,19) ')
                                //->orWhere('')
                                //->setParameter("dir", $respo->getServiceActuel())
                        ;
                }

                //dump($qb->getQuery());
                //die;

                return $qb->getQuery()->getResult();
        }

        public function regularisationconges($agent = null)
        {

                $qb = $this->getEntityManager()->createQueryBuilder();
                $qb = $qb->select("conges")
                        ->from('AgentBundle:Conges', 'conges')
                        ->where('conges.datecreation >= conges.datedebut')
                        ->andWhere('conges.etat = :etat')
                        ->andWhere('conges.saafactor = :saafactor')
                        ->andWhere('conges.etatImpression = :etatImpression')
                        ->setParameter('etat', 3)
                        ->setParameter('etatImpression', 3)
                        ->setParameter('saafactor', $agent);

                return $qb->getQuery()->getResult();
        }

        public function checkconges($exercice = null, $agent = null, $typeconge = null, $nbrejours = null, $id = 0)
        {
                $qb = $this->getEntityManager()->createQueryBuilder();
                $qb = $qb->select(" case when (IFNULL(sum(conges.nbrejours),0) + :nbrejours) <=30 then 1 else 0 end as t ") //(sum(conges.nbrejours) +  :nbrejours),
                        ->from('AgentBundle:Conges', 'conges')
                        ->where('conges.datecreation >= conges.datedebut')
                        ->andWhere('conges.etat = :etat')
                        ->andWhere('conges.agent = :agent')
                        ->andWhere('conges.typeConges = :typeConges')
                        ->andWhere('conges.exercice = :exercice');
                if ($id > 0) {
                        $qb = $qb->andWhere('conges.id <> :id')
                                ->setParameter('id', $id);
                }
                // ->andWhere('(sum(conges.nbrejours) +  :nbrejours) <=30')
                $qb = $qb->setParameter('nbrejours', $nbrejours)
                        ->setParameter('etat', 3)
                        ->setParameter('agent', $agent)
                        ->setParameter('typeConges', $typeconge)
                        ->setParameter('exercice', $exercice)
                        //->groupBy('conges.typeConges, conges.exercice, conges.agent')
                ;

                return $qb->getQuery()->getOneOrNullResult();
        }

        public function getDecAgent($agent = null, $annee = null)
        {

                $qb = $this->getEntityManager()->createQueryBuilder();
                $qb = $qb->select("decag")
                        ->from('AgentBundle:DecisionAgent', 'decag')
                        ->innerJoin('decag.decision', 'dec')
                        ->innerJoin('dec.exercice', 'ex')
                        ->where('decag.agent = :agent and ex.annee=:annee')
                        ->orderBy('dec.date', 'DESC')
                        ->setParameter('agent', $agent)
                        ->setParameter('annee', $annee)
                        ->setMaxResults(1);

                return $qb->getQuery()->getOneOrNullResult();
        }
}
